_ALERT_BEEP_B64  = ""

# -------------------------------------------------------------------
# *** NEW: Risk Thresholds & Weights ***
# -------------------------------------------------------------------
# Adjust these to match your tailings dam design limits.

RISK_THRESHOLDS = {
    "level_cm": {
        "normal":   (0,    55),   # cm
        "alert":    (55,   65),
        "critical": (65,   9999),
    },
    "turb_ntu": {
        "normal":   (0,    3.0),  # NTU
        "alert":    (3.0,  5.0),
        "critical": (5.0,  9999),
    },
    "flow_lpm": {
        "normal":   (0,    8.0),  # L/min
        "alert":    (8.0,  12.0),
        "critical": (12.0, 9999),
    },
}

# Weight each sensor's contribution to the composite score (must sum to 1)
RISK_WEIGHTS = {
    "level_cm":  0.50,
    "turb_ntu":  0.30,
    "flow_lpm":  0.20,
}

RISK_SCORE_BANDS = {
    "Normal":   (0,    33),
    "Alert":    (33,   66),
    "High":     (66,   85),
    "Critical": (85,   101),
}

RISK_COLORS = {
    "Normal":   "#2ecc71",
    "Alert":    "#f39c12",
    "High":     "#e67e22",
    "Critical": "#e74c3c",
}


# -------------------------------------------------------------------
# Forecast helpers (unchanged from original)
# -------------------------------------------------------------------
def _freq_seconds(freq: str) -> int:
    freq = str(freq).strip().lower()
    if not freq.endswith("s"):
        raise ValueError(f"Only second-based freq supported, got {freq!r}")
    return int(freq[:-1])


def _prepare_recent_frame(raw_df: pd.DataFrame) -> pd.DataFrame:
    if "timestamp" not in raw_df.columns:
        raise ValueError("Input frame must contain 'timestamp'.")

    df = raw_df.copy()
    df["timestamp"] = pd.to_datetime(df["timestamp"], errors="coerce", utc=True)
    df = df.dropna(subset=["timestamp"])
    df["timestamp"] = df["timestamp"].dt.floor("1s")

    base_cols = [
        c
        for c in ["level_cm", "turb_ntu", "flow_lpm", "head_cm", "pressure_kPa"]
        if c in df.columns
    ]
    if not base_cols:
        raise ValueError("No base sensor columns found for forecasting.")

    keep = ["timestamp"] + base_cols
    df = df[keep]

    df = (
        df.sort_values("timestamp")
        .groupby("timestamp", as_index=True)[base_cols]
        .mean()
        .sort_index()
    )
    return df


def _make_features_recursive(
    prepared: pd.DataFrame,
    freq: str,
    win_s: int,          # largest window (kept for compat; actual wins derived below)
    lags_s,
    wins_s=None,         # explicit list of window sizes in seconds
) -> pd.DataFrame:
    """
    Feature engineering aligned with thesis Section 4.4:
    - Lags  : Eq 4.1  — φ_lag,i(t) = y(t−i) for i ∈ {1,2,3,5,10,20} steps
    - Rolling stats: Eq 4.2–4.5 — mean, std, min, max over w ∈ {5,10,15} min windows
    - Cross-variable: Eq 4.6 — level×flow (hydraulic flux proxy)
                      Eq 4.7 — turbidity/(flow+ε) (sediment transport efficiency)
    All features are strictly causal (no future info).
    """
    EPSILON = 1e-6   # stabiliser for division (Eq 4.7)

    if wins_s is None:
        wins_s = [300, 600, 900]   # 5, 10, 15 min default

    df = prepared.copy()
    df = df.asfreq(freq)
    df = df.infer_objects(copy=False)

    numeric_cols = df.select_dtypes(include=["number"]).columns.tolist()
    if numeric_cols:
        df[numeric_cols] = df[numeric_cols].interpolate("time").ffill().bfill()

    base_cols = df.columns.tolist()
    freq_s = _freq_seconds(freq)

    # ── Lagged features (Eq 4.1) ──
    for c in base_cols:
        for lag_sec in lags_s:
            steps = int(lag_sec / freq_s)
            if steps <= 0:
                continue
            df[f"{c}_lag{lag_sec}s"] = df[c].shift(steps)

    # ── Rolling statistics (Eq 4.2 – 4.5): mean, std, min, max ──
    for c in base_cols:
        for w in wins_s:
            win_label = f"{w}s"
            roll = df[c].rolling(win_label)
            df[f"{c}_rmean_{w}s"] = roll.mean()
            df[f"{c}_rstd_{w}s"]  = roll.std()
            df[f"{c}_rmin_{w}s"]  = roll.min()
            df[f"{c}_rmax_{w}s"]  = roll.max()

    # ── Cross-variable interaction terms (Eq 4.6, 4.7) ──
    level_col = next((c for c in base_cols if "level" in c), None)
    flow_col  = next((c for c in base_cols if "flow"  in c), None)
    turb_col  = next((c for c in base_cols if "turb"  in c), None)

    if level_col and flow_col:
        # Eq 4.6: hydraulic flux proxy = h(t) × q(t)
        df["interact_level_flow"] = df[level_col] * df[flow_col]

    if turb_col and flow_col:
        # Eq 4.7: sediment transport efficiency = C(t) / (q(t) + ε)
        df["ratio_turb_flow"] = df[turb_col] / (df[flow_col] + EPSILON)

    df = df.dropna()
    df = df.reset_index()
    if "index" in df.columns and "timestamp" not in df.columns:
        df = df.rename(columns={"index": "timestamp"})
    return df


def recursive_forecast(models: dict, meta: dict, prepared: pd.DataFrame) -> pd.DataFrame:
    if prepared.empty:
        return pd.DataFrame()

    if "timestamp" in prepared.columns:
        buf = prepared.set_index("timestamp").copy()
    else:
        buf = prepared.copy()
    buf = buf.sort_index()

    # Thesis Section 3.5: data sampled at 60-second interval
    freq = meta.get("freq", "60s")   # default MUST be 60s to match thesis data rate
    freq_s = _freq_seconds(freq)
    step_s = int(meta.get("step_s", freq_s))
    if step_s != freq_s:
        step_s = freq_s

    # Thesis Section 4.4: lags {1,2,3,5,10,20} steps × 60s = {60,120,180,300,600,1200}s
    # Thesis Section 4.4: rolling windows {5,10,15} min = {300,600,900}s
    default_lags   = [60, 120, 180, 300, 600, 1200]   # 6 lag steps as per Eq 4.1
    default_wins   = [300, 600, 900]                   # 5,10,15-min windows as per Eq 4.2–4.5
    win_s  = int(meta.get("win_s",  900))   # largest window = 15 min
    lags_s = meta.get("lags_s", default_lags)
    wins_s = meta.get("wins_s", default_wins)
    targets = meta.get("targets", list(models.keys()))

    horizon_seconds = int(meta.get("horizon_s", 3600))
    horizon_steps = max(2, int(math.ceil(horizon_seconds / step_s)))

    preds_acc = []

    for _ in range(horizon_steps):
        if len(buf) == 0:
            break

        lookback_rows = min(len(buf), int(meta.get("history_rows", 300)))
        last_slice = buf.iloc[-lookback_rows:].copy()

        fe = _make_features_recursive(last_slice, freq=freq, win_s=win_s, lags_s=lags_s, wins_s=wins_s)
        if fe.empty:
            break

        feature_cols = [
            c for c in fe.columns
            if c not in ["timestamp"] and not c.startswith("target_")
        ]
        X_last = fe[feature_cols].iloc[[-1]]

        next_time = buf.index[-1] + pd.Timedelta(seconds=step_s)
        yhat_row = {"timestamp": next_time}
        new_state = {"timestamp": next_time}

        for tgt_name, model in models.items():
            if targets and tgt_name not in targets:
                continue

            # ── Feature alignment: match columns to those seen during training ──
            # XGBoost stores feature names in model.feature_names_in_
            # If there's a mismatch the forecast will be wrong or crash silently.
            try:
                trained_cols = list(model.feature_names_in_)
                missing = [c for c in trained_cols if c not in X_last.columns]
                extra   = [c for c in X_last.columns if c not in trained_cols]
                if missing:
                    # Add missing columns as 0 (better than crashing)
                    for mc in missing:
                        X_last[mc] = 0.0
                if extra:
                    X_last = X_last.drop(columns=extra)
                X_pred = X_last[trained_cols]
            except AttributeError:
                # Older model without feature_names_in_ — use as-is
                X_pred = X_last

            y_val = float(model.predict(X_pred)[0])
            yhat_row[f"pred_{tgt_name}"] = y_val
            new_state[tgt_name] = y_val

        for name in ["level_cm", "turb_ntu", "flow_lpm", "pressure_kPa", "head_cm"]:
            if name not in new_state:
                if name in buf.columns:
                    new_state[name] = buf[name].iloc[-1]
                else:
                    new_state[name] = float("nan")

        preds_acc.append(yhat_row)

        new_df = pd.DataFrame([new_state]).set_index("timestamp")
        buf = pd.concat([buf, new_df])

    if not preds_acc:
        return pd.DataFrame()

    forecast_df = pd.DataFrame(preds_acc)
    forecast_df["timestamp"] = pd.to_datetime(forecast_df["timestamp"], utc=True)
    return forecast_df


# -------------------------------------------------------------------
# cache model loading
# -------------------------------------------------------------------
@st.cache_resource
def load_meta_and_models():
    if not META_PATH.exists():
        return None, None
    meta = joblib.load(META_PATH)

    models = {}
    model_files = meta.get("model_files", {})
    for tgt, fname in model_files.items():
        model_path = MODELS_DIR / fname
        if not model_path.exists():
            continue
        m = XGBRegressor()
        m.load_model(model_path)
        models[tgt] = m

    if not models:
        return None, None
    return meta, models


def compute_forecast_from_csv(history_minutes: int = 60):
    """
    Returns (history_df, forecast_df) where:
      history_df  — last `history_minutes` of ACTUAL sensor readings  (left of Now)
      forecast_df — next 60 minutes of XGBoost predictions            (right of Now)
    Both DataFrames use tz-naive local timestamps so Plotly renders them on the
    same continuous axis with the "Now" vline exactly at the boundary.
    """
    if not DATA_FILE.exists():
        return None, None

    meta, models = load_meta_and_models()
    if meta is None or models is None:
        return None, None

    df = pd.read_csv(DATA_FILE)
    required_cols = {"timestamp", "ultrasonic_cm", "turb_ntu", "flow_lpm"}
    if not required_cols.issubset(df.columns):
        return None, None

    df["timestamp"] = pd.to_datetime(df["timestamp"], utc=True, errors="coerce")
    df = df.dropna(subset=["timestamp"]).sort_values("timestamp")

    # Accept both turbidity_ntu (thesis schema) and turb_ntu (firmware)
    if "turbidity_ntu" in df.columns and "turb_ntu" not in df.columns:
        df = df.rename(columns={"turbidity_ntu": "turb_ntu"})

    df["level_cm"] = df["ultrasonic_cm"]
    df = df[["timestamp", "level_cm", "turb_ntu", "flow_lpm"]]

    # ── "Now" is the latest timestamp in the CSV ──────────────────────────────
    now_utc = df["timestamp"].max()

    # ── History window: last `history_minutes` of ACTUAL data ────────────────
    # We fetch a wider window for feature engineering (need ≥35 rows for lags),
    # but we only show the user the requested history_minutes on the chart.
    fetch_minutes  = max(history_minutes, 45)   # enough rows for lag features
    fetch_cutoff   = now_utc - timedelta(minutes=fetch_minutes)
    display_cutoff = now_utc - timedelta(minutes=history_minutes)

    full_recent = df[df["timestamp"] >= fetch_cutoff].copy()
    if full_recent.empty or len(full_recent) < 25:
        return None, None

    # What we show on the left (actual) side of the chart
    display_recent = df[df["timestamp"] >= display_cutoff].copy()

    # ── Run XGBoost recursive forecast ───────────────────────────────────────
    prepared = _prepare_recent_frame(full_recent)
    if prepared.empty:
        return None, None

    forecast_utc = recursive_forecast(models, meta, prepared)
    if forecast_utc.empty:
        return None, None

    # ── Trim forecast to exactly 60 minutes AHEAD of now ─────────────────────
    freq   = meta.get("freq", "60s")
    freq_s = _freq_seconds(freq)
    step_s = int(meta.get("step_s", freq_s))
    if step_s != freq_s:
        step_s = freq_s

    horizon_min   = 60   # always show 60 minutes into the future
    max_steps     = max(2, int(math.ceil((horizon_min * 60) / step_s)))
    forecast_utc  = forecast_utc.iloc[:max_steps].copy()

    # Keep ONLY forecast rows that are strictly AFTER now_utc
    # (recursive_forecast already starts one step_s after the last history row,
    #  so this is just a safety guard)
    forecast_utc = forecast_utc[forecast_utc["timestamp"] > now_utc].copy()
    if forecast_utc.empty:
        return None, None

    # ── Convert both to tz-naive local time for consistent Plotly rendering ──
    def _to_local_naive(ts_series):
        return ts_series.dt.tz_convert(LOCAL_TZ).dt.tz_localize(None)

    display_recent = display_recent.copy()
    display_recent["timestamp"] = _to_local_naive(display_recent["timestamp"])

    forecast_local = forecast_utc.copy()
    forecast_local["timestamp"] = _to_local_naive(forecast_local["timestamp"])

    return display_recent, forecast_local


# -------------------------------------------------------------------
# Raw data loader
# -------------------------------------------------------------------
def load_data() -> pd.DataFrame:
    if not DATA_FILE.exists():
        return pd.DataFrame()

    df = pd.read_csv(DATA_FILE)
    if "timestamp" not in df.columns:
        return pd.DataFrame()

    ts_utc = pd.to_datetime(df["timestamp"], utc=True, errors="coerce")
    ts_local = ts_utc.dt.tz_convert(LOCAL_TZ).dt.tz_localize(None)

    df["timestamp"] = ts_local
    df = df.dropna(subset=["timestamp"])
    df = df.sort_values("timestamp")
    return df


def force_rerun():
    if hasattr(st, "rerun"):
        st.rerun()
    elif hasattr(st, "experimental_rerun"):
        st.experimental_rerun()


# -------------------------------------------------------------------
# Embedded buzzer API (FastAPI in background thread)
# -------------------------------------------------------------------
_buzzer_app = FastAPI(title="Buzzer Status API")

@_buzzer_app.get("/buzzer_status")
def _buzzer_status():
    """Returns {buzzer: 1} when forecast risk is Alert/High/Critical, else 0."""
    try:
        val = BUZZER_FLAG.read_text().strip()
        state = 1 if val == "1" else 0
    except FileNotFoundError:
        state = 0
    except Exception:
        state = 0
    return JSONResponse(content={"buzzer": state})

@_buzzer_app.get("/")
def _buzzer_root():
    return {"message": "Buzzer API running. Use GET /buzzer_status"}


@st.cache_resource
def start_buzzer_server():
    """
    Start the FastAPI buzzer server in a daemon thread.
    st.cache_resource guarantees this runs only ONCE across all Streamlit reruns.
    """
    def _run():
        uvicorn.run(
            _buzzer_app,
            host="0.0.0.0",
            port=BUZZER_API_PORT,
            log_level="warning",   # keep Streamlit output clean
        )
    t = threading.Thread(target=_run, daemon=True, name="buzzer-api")
    t.start()
    return t


def write_buzzer_flag(active: bool):
    """
    Write 1 (buzzer ON) or 0 (buzzer OFF) to buzzer_alert.txt.
    The embedded FastAPI thread reads this file and serves it to the Arduino.
    """
    try:
        BUZZER_FLAG.write_text("1" if active else "0")
    except Exception:
        pass  # never crash the dashboard over a flag write


def play_dashboard_sound(alert: bool):
    """
    Inject a tiny HTML audio snippet into the Streamlit page.
    alert=True  → urgent triple-beep  (A5, 880 Hz)
    alert=False → soft double-beep    (C5, 523 Hz)
    The audio plays automatically once; autoplay works because it is
    triggered by a user-session render cycle, not a background thread.
    """
    b64  = _ALERT_BEEP_B64 if alert else _NORMAL_BEEP_B64
    html = f"""
    <audio id="dashAudio" autoplay>
      <source src="data:audio/wav;base64,{b64}" type="audio/wav">
    </audio>
    <script>
      // Force play in case autoplay was deferred
      var a = document.getElementById('dashAudio');
      if (a) {{ a.play().catch(function(){{}}); }}
    </script>
    """
    _stc.html(html, height=0)


# -------------------------------------------------------------------
# *** NEW: Composite Risk Scoring Functions ***
# -------------------------------------------------------------------

def _sensor_score(value: float, sensor: str) -> float:
    """
    Map a raw sensor value to a 0–100 risk score for that sensor.

    Scoring bands (linear interpolation within each band):
      Normal   → 0–33
      Alert    → 33–66
      Critical → 66–100
    """
    if sensor not in RISK_THRESHOLDS or np.isnan(value):
        return 0.0

    bands = RISK_THRESHOLDS[sensor]
    n_lo, n_hi = bands["normal"]
    a_lo, a_hi = bands["alert"]
    c_lo, c_hi = bands["critical"]

    if value <= n_hi:
        # Normal band → 0 to 33
        span = n_hi - n_lo if n_hi != n_lo else 1
        frac = max(0.0, min(1.0, (value - n_lo) / span))
        return frac * 33.0
    elif value <= a_hi:
        # Alert band → 33 to 66
        span = a_hi - a_lo if a_hi != a_lo else 1
        frac = max(0.0, min(1.0, (value - a_lo) / span))
        return 33.0 + frac * 33.0
    else:
        # Critical band → 66 to 100
        span = c_hi - c_lo if c_hi != c_lo else 1
        frac = max(0.0, min(1.0, (value - c_lo) / span))
        return 66.0 + frac * 34.0


def _composite_score(level: float, turb: float, flow: float) -> float:
    """Weighted composite risk score (0–100)."""
    s_level = _sensor_score(level, "level_cm")
    s_turb  = _sensor_score(turb,  "turb_ntu")
    s_flow  = _sensor_score(flow,  "flow_lpm")

    w = RISK_WEIGHTS
    return (
        w["level_cm"] * s_level
        + w["turb_ntu"] * s_turb
        + w["flow_lpm"] * s_flow
    )


def _score_label(score: float) -> str:
    for label, (lo, hi) in RISK_SCORE_BANDS.items():
        if lo <= score < hi:
            return label
    return "Critical"


def compute_risk_timeline(
    recent_df: pd.DataFrame,
    forecast_df: pd.DataFrame,
) -> pd.DataFrame:
    """
    Compute per-row composite risk score for both historical and forecast windows.

    Returns a DataFrame with columns:
        timestamp, level, turb, flow, risk_score, risk_label, segment
    """
    rows = []

    # --- Historical segment ---
    hist = recent_df.copy()
    for _, r in hist.iterrows():
        level = r.get("level_cm", float("nan"))
        turb  = r.get("turb_ntu",  float("nan"))
        flow  = r.get("flow_lpm",  float("nan"))
        score = _composite_score(level, turb, flow)
        rows.append({
            "timestamp":  r["timestamp"],
            "level":      level,
            "turb":       turb,
            "flow":       flow,
            "risk_score": score,
            "risk_label": _score_label(score),
            "segment":    "Actual",
        })

    # --- Forecast segment ---
    fore = forecast_df.copy()
    # Safety: keep only forecast rows strictly after the last actual timestamp
    if rows:
        last_actual_ts = pd.Timestamp(rows[-1]["timestamp"])
        fore = fore[pd.to_datetime(fore["timestamp"]) > last_actual_ts].copy()

    level_col = "pred_level_cm" if "pred_level_cm" in fore.columns else None
    turb_col  = "pred_turb_ntu"  if "pred_turb_ntu"  in fore.columns else None
    flow_col  = "pred_flow_lpm"  if "pred_flow_lpm"  in fore.columns else None

    for _, r in fore.iterrows():
        level = r[level_col] if level_col else float("nan")
        turb  = r[turb_col]  if turb_col  else float("nan")
        flow  = r[flow_col]  if flow_col  else float("nan")
        score = _composite_score(level, turb, flow)
        rows.append({
            "timestamp":  r["timestamp"],
            "level":      level,
            "turb":       turb,
            "flow":       flow,
            "risk_score": score,
            "risk_label": _score_label(score),
            "segment":    "Forecast",
        })

    return pd.DataFrame(rows).sort_values("timestamp").reset_index(drop=True)


def find_first_high_risk_time(risk_df: pd.DataFrame, threshold_label: str = "High") -> pd.Timestamp | None:
    """Return the first forecast timestamp where risk_label >= threshold_label."""
    label_order = {"Normal": 0, "Alert": 1, "High": 2, "Critical": 3}
    min_order = label_order.get(threshold_label, 2)
    fore = risk_df[risk_df["segment"] == "Forecast"].copy()
    matches = fore[fore["risk_label"].map(lambda x: label_order.get(x, 0)) >= min_order]
    if matches.empty:
        return None
    return matches.iloc[0]["timestamp"]


def render_risk_gauge(score: float, label: str):
    """Render a Plotly gauge for the current composite risk score."""
    color = RISK_COLORS.get(label, "#e74c3c")
    fig = go.Figure(go.Indicator(
        mode="gauge+number+delta",
        value=score,
        title={"text": f"Composite Risk Score<br><span style='font-size:1.1em;color:{color}'>{label}</span>"},
        gauge={
            "axis": {"range": [0, 100], "tickwidth": 1},
            "bar": {"color": color},
            "steps": [
                {"range": [0,  33],  "color": "#d5f5e3"},
                {"range": [33, 66],  "color": "#fef9e7"},
                {"range": [66, 85],  "color": "#fdebd0"},
                {"range": [85, 100], "color": "#fadbd8"},
            ],
            "threshold": {
                "line": {"color": "red", "width": 4},
                "thickness": 0.75,
                "value": 66,
            },
        },
        number={"suffix": " / 100"},
    ))
    fig.update_layout(height=280, margin=dict(l=20, r=20, t=60, b=20))
    return fig


def render_risk_timeline_chart(risk_df: pd.DataFrame, boundary_time):
    """
    Render composite risk score over time with colour-coded background bands
    and a vertical 'Now' line separating actual vs forecast.
    """
    fig = go.Figure()

    # Colour-coded background bands
    for band_label, (lo, hi) in RISK_SCORE_BANDS.items():
        fig.add_hrect(
            y0=lo, y1=hi,
            fillcolor=RISK_COLORS[band_label],
            opacity=0.08,
            layer="below",
            line_width=0,
            annotation_text=band_label,
            annotation_position="right",
        )

    # Actual segment
    actual = risk_df[risk_df["segment"] == "Actual"]
    if not actual.empty:
        fig.add_trace(go.Scatter(
            x=actual["timestamp"],
            y=actual["risk_score"],
            mode="lines",
            name="Actual Risk Score",
            line=dict(color="#2980b9", width=2),
        ))

    # Forecast segment
    fore = risk_df[risk_df["segment"] == "Forecast"]
    if not fore.empty:
        fig.add_trace(go.Scatter(
            x=fore["timestamp"],
            y=fore["risk_score"],
            mode="lines",
            name="Forecast Risk Score",
            line=dict(color="#e67e22", width=2, dash="dash"),
        ))

    # "Now" vertical line — must be Unix milliseconds (int) for datetime axes
    if boundary_time is not None:
        bt_ms = int(pd.to_datetime(boundary_time).timestamp() * 1000)
        fig.add_vline(
            x=bt_ms,
            line_dash="dot",
            line_width=2,
            line_color="grey",
            annotation_text="Now",
            annotation_position="top right",
        )

    fig.update_layout(
        title="Composite Risk Score – History + Forecast",
        xaxis_title="Date / Time",
        yaxis_title="Risk Score (0–100)",
        yaxis=dict(range=[0, 105]),
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1),
        margin=dict(l=20, r=20, t=60, b=20),
        height=350,
    )
    return fig


def render_per_sensor_risk_bars(latest_level, latest_turb, latest_flow,
                                  fore_level, fore_turb, fore_flow):
    """Side-by-side bar chart comparing current vs. peak forecast risk per sensor."""
    sensors = ["Level (cm)", "Turbidity (NTU)", "Flow (L/min)"]
    actual_scores = [
        _sensor_score(latest_level, "level_cm"),
        _sensor_score(latest_turb,  "turb_ntu"),
        _sensor_score(latest_flow,  "flow_lpm"),
    ]
    forecast_scores = [
        _sensor_score(fore_level, "level_cm"),
        _sensor_score(fore_turb,  "turb_ntu"),
        _sensor_score(fore_flow,  "flow_lpm"),
    ]

    fig = go.Figure(data=[
        go.Bar(name="Current (actual)", x=sensors, y=actual_scores,
               marker_color="#2980b9"),
        go.Bar(name="Peak Forecast",    x=sensors, y=forecast_scores,
               marker_color="#e67e22"),
    ])
    fig.update_layout(
        barmode="group",
        title="Per-Sensor Risk Score: Current vs. Peak Forecast",
        yaxis=dict(range=[0, 105], title="Risk Score"),
        legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1),
        height=300,
        margin=dict(l=20, r=20, t=60, b=20),
    )
    return fig


