# ─────────────────────────────────────────────────────────────────────────────
# Live feed fragment — re-renders data without a full page reload
# Requires Streamlit ≥ 1.37 for @st.fragment(run_every=...)
# ─────────────────────────────────────────────────────────────────────────────
def _make_live_fragment(history_minutes: int, refresh_interval: int):
    """
    Returns a fragment function bound to the given settings.
    We use a factory so the fragment captures the sidebar values.
    st.fragment(run_every=N) re-runs ONLY this function on the timer —
    the page header, CSS, and sidebar are NOT re-rendered.
    """
    @st.fragment(run_every=refresh_interval)
    def _fragment():
        # ── Load data ─────────────────────────────────────────────────────────────
        df = load_data()
        if df.empty:
            st.error(
                "⚠️ **No sensor data found** — `sensor_data.csv` is empty or missing.\n\n"
                "- Verify `server.py` is running (`uvicorn server:app --port 8501`)\n"
                "- Confirm the Arduino is posting to `/ingest` (check serial monitor for `200 OK`)"
            )
            return
        
        latest_ts   = df["timestamp"].max()
        cutoff      = latest_ts - timedelta(minutes=history_minutes)
        df_recent   = df[df["timestamp"] >= cutoff].copy()
        
        # ── Live KPI strip ───────────────────────────────────────────────────────
        latest_row = df_recent.iloc[-1] if not df_recent.empty else None
        
        def _delta_str(col, fmt=".1f"):
            if latest_row is None or len(df_recent) < 2:
                return ("flat", "—")
            prev = df_recent[col].iloc[-2] if col in df_recent.columns else None
            curr = latest_row.get(col, None)
            if prev is None or curr is None or pd.isna(prev) or pd.isna(curr):
                return ("flat", "—")
            diff = curr - prev
            cls  = "up" if diff > 0 else ("down" if diff < 0 else "flat")
            arrow = "▲" if diff > 0 else ("▼" if diff < 0 else "●")
            return (cls, f"{arrow} {abs(diff):{fmt}}")
        
        k1, k2, k3, k4, k5 = st.columns(5)
        cards = [
            (k1, "💧 Water Level", "ultrasonic_cm",   "cm",    ".1f"),
            (k2, "📊 Level %",     "water_level_pct", "%",     ".1f"),
            (k3, "🌊 Flow Rate",   "flow_lpm",        "L/min", ".2f"),
            (k4, "🔬 Turbidity",   "turb_ntu",        "NTU",   ".2f"),
            (k5, "⏱ Window",       None,              None,    None),
        ]
        for col_obj, label, field, unit, fmt in cards:
            with col_obj:
                if field and latest_row is not None and field in latest_row:
                    val = latest_row[field]
                    cls, delta = _delta_str(field, fmt) if fmt else ("flat", "—")
                    st.markdown(f"""
                    <div class="kpi-card">
                        <div class="kpi-label">{label}</div>
                        <div><span class="kpi-value">{val:{fmt}}</span>
                             <span class="kpi-unit">{unit}</span></div>
                        <div class="kpi-delta {cls}">{delta}</div>
                    </div>""", unsafe_allow_html=True)
                elif field is None:
                    st.markdown(f"""
                    <div class="kpi-card">
                        <div class="kpi-label">⏱ Window</div>
                        <div><span class="kpi-value">{history_minutes}</span>
                             <span class="kpi-unit">min</span></div>
                        <div class="kpi-delta flat">{len(df_recent)} samples</div>
                    </div>""", unsafe_allow_html=True)
                else:
                    st.markdown(f"""
                    <div class="kpi-card">
                        <div class="kpi-label">{label}</div>
                        <div class="kpi-value" style="font-size:1rem;color:#bbb">N/A</div>
                    </div>""", unsafe_allow_html=True)
        
        st.markdown("<div style='margin-bottom:8px'></div>", unsafe_allow_html=True)
        
        # ── Raw sensor charts ─────────────────────────────────────────────────────
        st.markdown("""<div class="section-header">
            <span class="section-icon">📡</span>
            <h3>Live Sensor Data</h3>
            <span style="margin-left:auto;font-size:0.75rem;color:#9aa5b0">
                Last {} min · {} samples
            </span></div>""".format(history_minutes, len(df_recent)),
            unsafe_allow_html=True)
        
        top_left, top_right = st.columns(2)
        bottom_left, bottom_right = st.columns(2)
        
        with top_left:
            st.markdown('<div class="chart-card">', unsafe_allow_html=True)
            st.subheader("💧 Water Level (cm)")
            if "ultrasonic_cm" in df_recent.columns:
                fig_ultra = px.scatter(df_recent, x="timestamp", y="ultrasonic_cm",
                                       title="Water Level (Ultrasonic)")
                fig_ultra.update_traces(mode="lines+markers")
                fig_ultra.update_layout(xaxis_title="Date / Time", yaxis_title="Ultrasonic (cm)", template="plotly_white", height=280, margin=dict(l=0,r=0,t=40,b=0))
                st.plotly_chart(fig_ultra, use_container_width=True)
            else:
                st.warning("Column 'ultrasonic_cm' not found in sensor_data.csv")
            st.markdown('</div>', unsafe_allow_html=True)
        
        with top_right:
            st.markdown('<div class="chart-card">', unsafe_allow_html=True)
            st.subheader("📊 Water Level (%)")
            if "water_level_pct" in df_recent.columns:
                fig_water = px.scatter(df_recent, x="timestamp", y="water_level_pct",
                                       title="Water Level (%)")
                fig_water.update_traces(mode="lines+markers")
                fig_water.update_layout(xaxis_title="Date / Time", yaxis_title="Water Level (%)", template="plotly_white", height=280, margin=dict(l=0,r=0,t=40,b=0))
                st.plotly_chart(fig_water, use_container_width=True)
            else:
                st.warning("Column 'water_level_pct' not found in sensor_data.csv")
            st.markdown('</div>', unsafe_allow_html=True)
        
        with bottom_left:
            st.markdown('<div class="chart-card">', unsafe_allow_html=True)
            st.subheader("🔄 Flow Rate (L/min)")
            if "flow_lpm" in df_recent.columns:
                fig_flow = px.scatter(df_recent, x="timestamp", y="flow_lpm",
                                      title="Flow Rate")
                fig_flow.update_traces(mode="lines+markers")
                fig_flow.update_layout(xaxis_title="Date / Time", yaxis_title="Flow Rate (L/min)", template="plotly_white", height=280, margin=dict(l=0,r=0,t=40,b=0))
                st.plotly_chart(fig_flow, use_container_width=True)
            else:
                st.warning("Column 'flow_lpm' not found in sensor_data.csv")
            st.markdown('</div>', unsafe_allow_html=True)
        
        with bottom_right:
            st.markdown('<div class="chart-card">', unsafe_allow_html=True)
            st.subheader("🔬 Turbidity (NTU)")
            if "turb_ntu" in df_recent.columns:
                fig_turb = px.scatter(df_recent, x="timestamp", y="turb_ntu",
                                      title="Turbidity")
                fig_turb.update_traces(mode="lines+markers")
                fig_turb.update_layout(xaxis_title="Date / Time", yaxis_title="Turbidity (NTU)", template="plotly_white", height=280, margin=dict(l=0,r=0,t=40,b=0))
                st.plotly_chart(fig_turb, use_container_width=True)
            else:
                st.warning("Column 'turb_ntu' not found in sensor_data.csv")
            st.markdown('</div>', unsafe_allow_html=True)
        
        # ----------------------------------------------------------------
        # Forecast charts (unchanged logic, matching Figure 4.8)
        # ----------------------------------------------------------------
        st.markdown("""<div class="section-header">
            <span class="section-icon">🔮</span>
            <h3>XGBoost Forecast — 60-Minute Ahead Predictions</h3>
            <span style="margin-left:auto;font-size:0.75rem;color:#9aa5b0">
                Solid = Actual · Dashed = Forecast · ┊ = Now
            </span></div>""", unsafe_allow_html=True)
        
        recent_for_model, forecast_df = compute_forecast_from_csv(history_minutes=60)
        
        if recent_for_model is None or forecast_df is None or forecast_df.empty:
            st.warning(
                "⚠️ Forecast not available yet. Possible reasons:\n\n"
                "1. **Model files missing** — need `model_meta_recursive.joblib` and `models/` directory.\n"
                "2. **Not enough data** — dashboard needs ≥ 25 rows at 60-second intervals "
                "(~25 minutes of history) to build lag & rolling features.\n"
                "3. **Column names** — `sensor_data.csv` must have `ultrasonic_cm`, `turb_ntu` "
                "(or `turbidity_ntu`), and `flow_lpm`.\n"
                "4. **Feature mismatch** — the model was trained with cross-variable features "
                "(level×flow, turb/flow). Ensure training used the same pipeline.\n\n"
                "Check the **Forecast Diagnostics** expander below for details."
            )
            with st.expander("🔍 Forecast Diagnostics"):
                meta_ok, models_ok = load_meta_and_models()
                st.write("model_meta_recursive.joblib found:", META_PATH.exists())
                st.write("models/ directory found:", MODELS_DIR.exists())
                st.write("sensor_data.csv found:", DATA_FILE.exists())
                if DATA_FILE.exists():
                    _diag = pd.read_csv(DATA_FILE)
                    st.write("CSV columns:", list(_diag.columns))
                    st.write("CSV row count:", len(_diag))
                if meta_ok:
                    st.write("Meta keys:", list(meta_ok.keys()))
                    st.write("Meta freq:", meta_ok.get("freq", "NOT SET"))
                    st.write("Meta lags_s:", meta_ok.get("lags_s", "NOT SET"))
                    st.write("Meta wins_s:", meta_ok.get("wins_s", "NOT SET"))
                    st.write("Meta targets:", meta_ok.get("targets", "NOT SET"))
                if models_ok:
                    for tgt, m in models_ok.items():
                        try:
                            st.write(f"Model '{tgt}' trained features ({len(m.feature_names_in_)}):",
                                     list(m.feature_names_in_))
                        except AttributeError:
                            st.write(f"Model '{tgt}': no feature_names_in_ attribute")
            return  # Can't do risk panel without forecasts
        
        # boundary_time = last actual observation = "Now" on the chart
        # Both recent_for_model and forecast_df are tz-naive local time after the fix.
        boundary_time    = pd.Timestamp(recent_for_model["timestamp"].max())
        boundary_time_ms = int(boundary_time.timestamp() * 1000)
        
        # forecast_df already contains ONLY timestamps > boundary_time (enforced in
        # compute_forecast_from_csv), but we add the filter here as a safety guard.
        def _safe_fore(df_fore, col):
            """Return forecast rows strictly after Now, with robust type comparison."""
            mask = pd.to_datetime(df_fore["timestamp"]) > boundary_time
            return df_fore[mask]
        
        def _make_forecast_fig(hist_x, hist_y, fore_x, fore_y, title, yaxis_label,
                               hist_label=None, fore_label=None):
            """
            Solid line = actual history (left of Now).
            Dotted line = XGBoost forecast (right of Now, into the NEXT 60 min).
            Vertical dotted grey line = Now boundary.
            """
            n_hist = len(hist_x) if hasattr(hist_x, '__len__') else 0
            n_fore = len(fore_x) if hasattr(fore_x, '__len__') else 0
            h_label = hist_label or f"Actual (last {history_minutes} min, {n_hist} pts)"
            f_label = fore_label or f"Forecast (next 60 min, {n_fore} pts)"
        
            fig = go.Figure()
            fig.add_trace(go.Scatter(
                x=hist_x, y=hist_y,
                mode="lines",
                name=h_label,
                line=dict(color="#1f77b4", width=2),
            ))
            fig.add_trace(go.Scatter(
                x=fore_x, y=fore_y,
                mode="lines",
                name=f_label,
                line=dict(color="#ff7f0e", width=2, dash="dot"),   # orange = forecast
            ))
            fig.add_vline(x=boundary_time_ms, line_dash="dot", line_width=2, line_color="grey")
            fig.add_annotation(
                x=boundary_time_ms, y=1.02, xref="x", yref="paper",
                text="Now", showarrow=False, yanchor="bottom", font=dict(size=12),
            )
            fig.update_layout(
                title=dict(text=title, font=dict(size=13, color="#1a2533")),
                xaxis_title="Date / Time",
                yaxis_title=yaxis_label,
                template="plotly_white",
                height=300,
                margin=dict(l=0, r=0, t=44, b=0),
                legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="right", x=1,
                            font=dict(size=11)),
                paper_bgcolor="rgba(0,0,0,0)",
                plot_bgcolor="rgba(0,0,0,0)",
            )
            return fig
        
        # ── Debug info (collapsible) ──────────────────────────────────────────────
        with st.expander("📊 Forecast data info", expanded=False):
            st.write(f"**Now (boundary):** {boundary_time}")
            st.write(f"**History rows:** {len(recent_for_model)}, "
                     f"from {recent_for_model['timestamp'].min()} "
                     f"to {recent_for_model['timestamp'].max()}")
            st.write(f"**Forecast rows:** {len(forecast_df)}, "
                     f"from {forecast_df['timestamp'].min()} "
                     f"to {forecast_df['timestamp'].max()}")
            st.write("**Forecast columns:**", list(forecast_df.columns))
        
        col_a, col_b = st.columns(2)
        
        with col_a:
            if "level_cm" in recent_for_model.columns and "pred_level_cm" in forecast_df.columns:
                fore_level = _safe_fore(forecast_df, "pred_level_cm")
                st.caption(f"Level forecast: {len(fore_level)} points after Now")
                fig_level = _make_forecast_fig(
                    hist_x=recent_for_model["timestamp"],
                    hist_y=recent_for_model["level_cm"],
                    fore_x=fore_level["timestamp"],
                    fore_y=fore_level["pred_level_cm"],
                    title="Level / Ultrasonic – history + forecast",
                    yaxis_label="Level (cm)",
                )
                st.plotly_chart(fig_level, use_container_width=True)
            else:
                st.warning("Level forecast columns not available.")
        
        with col_b:
            if "turb_ntu" in recent_for_model.columns and "pred_turb_ntu" in forecast_df.columns:
                fore_turb = _safe_fore(forecast_df, "pred_turb_ntu")
                st.caption(f"Turbidity forecast: {len(fore_turb)} points after Now")
                fig_turb2 = _make_forecast_fig(
                    hist_x=recent_for_model["timestamp"],
                    hist_y=recent_for_model["turb_ntu"],
                    fore_x=fore_turb["timestamp"],
                    fore_y=fore_turb["pred_turb_ntu"],
                    title="Turbidity – history + forecast",
                    yaxis_label="Turbidity (NTU)",
                )
                st.plotly_chart(fig_turb2, use_container_width=True)
            else:
                st.warning("Turbidity forecast columns not available.")
        
        if "flow_lpm" in recent_for_model.columns and "pred_flow_lpm" in forecast_df.columns:
            fore_flow = _safe_fore(forecast_df, "pred_flow_lpm")
            st.caption(f"Flow forecast: {len(fore_flow)} points after Now")
            fig_flow2 = _make_forecast_fig(
                hist_x=recent_for_model["timestamp"],
                hist_y=recent_for_model["flow_lpm"],
                fore_x=fore_flow["timestamp"],
                fore_y=fore_flow["pred_flow_lpm"],
                title="Flow – history + forecast",
                yaxis_label="Flow (L/min)",
            )
            st.plotly_chart(fig_flow2, use_container_width=True)
        else:
            st.warning("Flow forecast columns not available.")
        
        # ================================================================
        # *** NEW: Composite Risk Dashboard ***
        # ================================================================
        st.markdown("""<div class="section-header">
            <span class="section-icon">🛡️</span>
            <h3>Composite Risk Dashboard</h3>
            <span style="margin-left:auto;font-size:0.75rem;color:#9aa5b0">
                Weighted score: Level 50% · Turbidity 30% · Flow 20%
            </span></div>""", unsafe_allow_html=True)
        
        # Compute risk timeline
        risk_df = compute_risk_timeline(recent_for_model, forecast_df)
        
        # --- Current live risk ---
        actual_risk = risk_df[risk_df["segment"] == "Actual"]
        current_row = actual_risk.iloc[-1] if not actual_risk.empty else None
        
        # --- Peak forecast risk ---
        fore_risk = risk_df[risk_df["segment"] == "Forecast"]
        peak_fore_row = fore_risk.loc[fore_risk["risk_score"].idxmax()] if not fore_risk.empty else None
        
        # --- Lead time: first time forecast enters High or Critical ---
        first_high_ts = find_first_high_risk_time(risk_df, threshold_label="High")
        if first_high_ts is not None and current_row is not None:
            lead_minutes = (
                pd.to_datetime(first_high_ts) - pd.to_datetime(current_row["timestamp"])
            ).total_seconds() / 60.0
        else:
            lead_minutes = None
        
        # --- Buzzer flag: ON when ANY forecast row is Alert / High / Critical ---
        BUZZER_TRIGGER_LABELS = {"Alert", "High", "Critical"}
        forecast_risk_labels = set(fore_risk["risk_label"].unique()) if not fore_risk.empty else set()
        buzzer_should_be_on  = bool(forecast_risk_labels & BUZZER_TRIGGER_LABELS)
        write_buzzer_flag(buzzer_should_be_on)
        play_dashboard_sound(alert=buzzer_should_be_on)
        
        # ---- Row 1: Current gauge + KPI cards ----
        gauge_col, kpi_col = st.columns([1, 2])
        
        with gauge_col:
            if current_row is not None:
                cur_score = current_row["risk_score"]
                cur_label = current_row["risk_label"]
                st.plotly_chart(
                    render_risk_gauge(cur_score, cur_label),
                    use_container_width=True,
                )
            else:
                st.info("No actual data to compute current risk score.")
        
        with kpi_col:
            st.markdown("#### Key Risk Indicators")
            k1, k2, k3 = st.columns(3)
        
            with k1:
                if current_row is not None:
                    lbl = current_row["risk_label"]
                    col = RISK_COLORS.get(lbl, "#999")
                    st.markdown(
                        f"<div style='background:{col}20;border-left:5px solid {col};"
                        f"padding:12px;border-radius:6px'>"
                        f"<b>Current Status</b><br>"
                        f"<span style='font-size:1.6em;color:{col}'><b>{lbl}</b></span><br>"
                        f"Score: {current_row['risk_score']:.1f}/100"
                        f"</div>",
                        unsafe_allow_html=True,
                    )
        
            with k2:
                if peak_fore_row is not None:
                    lbl = peak_fore_row["risk_label"]
                    col = RISK_COLORS.get(lbl, "#999")
                    st.markdown(
                        f"<div style='background:{col}20;border-left:5px solid {col};"
                        f"padding:12px;border-radius:6px'>"
                        f"<b>Peak Forecast Risk</b><br>"
                        f"<span style='font-size:1.6em;color:{col}'><b>{lbl}</b></span><br>"
                        f"Score: {peak_fore_row['risk_score']:.1f}/100"
                        f"</div>",
                        unsafe_allow_html=True,
                    )
        
            with k3:
                if lead_minutes is not None:
                    lbl_color = "#e67e22" if lead_minutes < 15 else "#2ecc71"
                    st.markdown(
                        f"<div style='background:{lbl_color}20;border-left:5px solid {lbl_color};"
                        f"padding:12px;border-radius:6px'>"
                        f"<b>Predictive Lead Time</b><br>"
                        f"<span style='font-size:1.6em;color:{lbl_color}'>"
                        f"<b>{lead_minutes:.1f} min</b></span><br>"
                        f"until HIGH risk (forecast-driven)"
                        f"</div>",
                        unsafe_allow_html=True,
                    )
                else:
                    st.markdown(
                        "<div style='background:#2ecc7120;border-left:5px solid #2ecc71;"
                        "padding:12px;border-radius:6px'>"
                        "<b>Predictive Lead Time</b><br>"
                        "<span style='font-size:1.6em;color:#2ecc71'><b>No HIGH risk</b></span><br>"
                        "forecast remains safe"
                        "</div>",
                        unsafe_allow_html=True,
                    )
        
        # ---- Buzzer status banner ----
        if buzzer_should_be_on:
            st.error(
                "🔔 **BUZZER ACTIVE** — Forecast predicts **Alert or higher** risk. "
                "Pin 7 buzzer is signalling on the Arduino.",
                icon="🚨",
            )
        else:
            st.success("✅ Buzzer OFF — Forecast risk is Normal.", icon="🔕")
        
        # ---- Row 2: Risk timeline chart ----
        st.plotly_chart(
            render_risk_timeline_chart(risk_df, boundary_time_ms),
            use_container_width=True,
        )
        
        # ---- Row 3: Per-sensor risk bar chart ----
        if current_row is not None and peak_fore_row is not None:
            st.plotly_chart(
                render_per_sensor_risk_bars(
                    latest_level=current_row["level"],
                    latest_turb=current_row["turb"],
                    latest_flow=current_row["flow"],
                    fore_level=peak_fore_row["level"],
                    fore_turb=peak_fore_row["turb"],
                    fore_flow=peak_fore_row["flow"],
                ),
                use_container_width=True,
            )
        
        # ---- Row 4: Sensor status table ----
        st.markdown("#### Sensor Status at Current + Peak Forecast Moment")
        
        def status_badge(score):
            lbl = _score_label(score)
            col = RISK_COLORS.get(lbl, "#999")
            return f"<span style='background:{col};color:white;padding:2px 8px;border-radius:4px'>{lbl}</span>"
        
        if current_row is not None and peak_fore_row is not None:
            table_data = {
                "Sensor": ["Level (cm)", "Turbidity (NTU)", "Flow (L/min)"],
                "Current Value": [
                    f"{current_row['level']:.2f}",
                    f"{current_row['turb']:.3f}",
                    f"{current_row['flow']:.3f}",
                ],
                "Current Score": [
                    f"{_sensor_score(current_row['level'], 'level_cm'):.1f}",
                    f"{_sensor_score(current_row['turb'],  'turb_ntu'):.1f}",
                    f"{_sensor_score(current_row['flow'],  'flow_lpm'):.1f}",
                ],
                "Status (now)": [
                    status_badge(_sensor_score(current_row['level'], 'level_cm')),
                    status_badge(_sensor_score(current_row['turb'],  'turb_ntu')),
                    status_badge(_sensor_score(current_row['flow'],  'flow_lpm')),
                ],
                "Peak Forecast Value": [
                    f"{peak_fore_row['level']:.2f}",
                    f"{peak_fore_row['turb']:.3f}",
                    f"{peak_fore_row['flow']:.3f}",
                ],
                "Peak Forecast Score": [
                    f"{_sensor_score(peak_fore_row['level'], 'level_cm'):.1f}",
                    f"{_sensor_score(peak_fore_row['turb'],  'turb_ntu'):.1f}",
                    f"{_sensor_score(peak_fore_row['flow'],  'flow_lpm'):.1f}",
                ],
                "Status (forecast)": [
                    status_badge(_sensor_score(peak_fore_row['level'], 'level_cm')),
                    status_badge(_sensor_score(peak_fore_row['turb'],  'turb_ntu')),
                    status_badge(_sensor_score(peak_fore_row['flow'],  'flow_lpm')),
                ],
            }
            st.markdown(
                pd.DataFrame(table_data).to_html(escape=False, index=False),
                unsafe_allow_html=True,
            )
        
        # ---- Row 5: Risk timeline table ----
        with st.expander("📋 Full risk timeline table"):
            st.dataframe(
                risk_df[["timestamp", "segment", "level", "turb", "flow",
                          "risk_score", "risk_label"]].round(3),
                use_container_width=True,
            )
        
        # ---- Standard raw data expander ----
        with st.expander("🗂️ Raw sensor data table (recent window)"):
            show_cols = [
                c for c in df_recent.columns
                if c in ("timestamp", "ultrasonic_cm", "water_level_pct", "flow_lpm", "turb_ntu")
            ]
            st.dataframe(df_recent[show_cols].tail(200))

    return _fragment

def main():
    # Start the embedded buzzer API server (runs once, persists across reruns)
    start_buzzer_server()

    st.set_page_config(
        page_title="TSF Monitoring | AI Dashboard",
        page_icon="🛡️",
        layout="wide",
        initial_sidebar_state="expanded",
    )

    # ── Global CSS ────────────────────────────────────────────────────────────
    st.markdown("""
    <style>
    @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

    html, body, [class*="css"] { font-family: 'Inter', sans-serif; }

    /* Dark header bar */
    .tsf-header {
        background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%);
        border-radius: 12px;
        padding: 24px 32px;
        margin-bottom: 24px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        box-shadow: 0 4px 20px rgba(0,0,0,0.3);
    }
    .tsf-header h1 {
        color: #ffffff;
        font-size: 1.7rem;
        font-weight: 700;
        margin: 0;
        letter-spacing: -0.5px;
    }
    .tsf-header .subtitle {
        color: #94b8c4;
        font-size: 0.85rem;
        margin-top: 4px;
    }
    .tsf-badge {
        background: rgba(255,255,255,0.1);
        border: 1px solid rgba(255,255,255,0.2);
        border-radius: 20px;
        padding: 6px 16px;
        color: #e0f0ff;
        font-size: 0.78rem;
        font-weight: 500;
        white-space: nowrap;
    }

    /* KPI metric cards */
    .kpi-card {
        background: #ffffff;
        border: 1px solid #e8ecf0;
        border-radius: 10px;
        padding: 16px 20px;
        box-shadow: 0 2px 8px rgba(0,0,0,0.06);
        transition: box-shadow 0.2s;
    }
    .kpi-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,0.1); }
    .kpi-label { font-size: 0.72rem; color: #7b8a99; font-weight: 600;
                 text-transform: uppercase; letter-spacing: 0.6px; margin-bottom: 4px; }
    .kpi-value { font-size: 1.6rem; font-weight: 700; color: #1a2533; line-height: 1; }
    .kpi-unit  { font-size: 0.8rem; color: #9aa5b0; margin-left: 3px; }
    .kpi-delta { font-size: 0.75rem; margin-top: 4px; }
    .kpi-delta.up   { color: #e74c3c; }
    .kpi-delta.down { color: #27ae60; }
    .kpi-delta.flat { color: #7b8a99; }

    /* Section headers */
    .section-header {
        display: flex; align-items: center; gap: 10px;
        border-bottom: 2px solid #e8ecf0;
        padding-bottom: 8px; margin: 28px 0 16px 0;
    }
    .section-header h3 {
        font-size: 1rem; font-weight: 600; color: #1a2533; margin: 0;
        text-transform: uppercase; letter-spacing: 0.5px;
    }
    .section-icon { font-size: 1.1rem; }

    /* Sidebar */
    section[data-testid="stSidebar"] {
        background: #f7f9fc;
        border-right: 1px solid #e1e8ef;
    }
    .sidebar-brand {
        background: linear-gradient(135deg, #0f2027, #2c5364);
        border-radius: 8px; padding: 12px 14px; margin-bottom: 16px;
        text-align: center;
    }
    .sidebar-brand span { color: #ffffff; font-weight: 700; font-size: 0.9rem; }
    .sidebar-brand small { display:block; color: #94b8c4; font-size: 0.72rem; }

    /* Status indicator dot */
    .status-dot {
        display: inline-block; width: 9px; height: 9px;
        border-radius: 50%; margin-right: 6px;
        animation: pulse 2s infinite;
    }
    .status-dot.live  { background: #2ecc71; }
    .status-dot.warn  { background: #f39c12; }
    .status-dot.crit  { background: #e74c3c; }
    @keyframes pulse {
        0%,100% { opacity:1; } 50% { opacity:0.4; }
    }

    /* Chart containers */
    .chart-card {
        background: #ffffff; border: 1px solid #e8ecf0;
        border-radius: 10px; padding: 4px;
        box-shadow: 0 2px 8px rgba(0,0,0,0.05);
    }

    /* Scrolling data table */
    .stDataFrame { border-radius: 8px; overflow: hidden; }

    /* Hide Streamlit default header chrome */
    #MainMenu, footer { visibility: hidden; }
    header[data-testid="stHeader"] { background: transparent; }

    /* Responsive tweaks */
    .block-container { padding-top: 1rem !important; max-width: 1400px; }
    </style>
    """, unsafe_allow_html=True)

    # ── Sidebar ───────────────────────────────────────────────────────────────
    with st.sidebar:
        st.markdown("""
        <div class="sidebar-brand">
            <span>🛡️ TSF Monitor</span>
            <small>AI-Driven IoT Framework</small>
        </div>
        """, unsafe_allow_html=True)

        st.markdown("**⚙️ View Options**")
        history_minutes = st.slider(
            "History window (minutes)",
            min_value=5, max_value=240, value=60, step=5,
        )

        col_ref, col_auto = st.columns(2)
        with col_ref:
            if st.button("🔄 Refresh", use_container_width=True):
                force_rerun()

        st.markdown("---")
        st.markdown("**🔁 Auto-Refresh**")
        auto_refresh = st.toggle("Enable", value=True)
        refresh_interval = st.select_slider(
            "Interval (seconds)",
            options=[5, 10, 15, 30, 60, 120],
            value=10,
            disabled=not auto_refresh,
        )
        if auto_refresh:
            st.caption(f"⏱ Refreshing every **{refresh_interval}s**")
            _stc.html(f"""
            <script>
              var _r = {refresh_interval};
              var _el = window.parent.document.getElementById('arc');
              function _tick() {{
                _r -= 1;
                if (_el) _el.innerText = '⏱ Next in ' + _r + 's';
                if (_r <= 0) window.parent.location.reload();
                else setTimeout(_tick, 1000);
              }}
              setTimeout(_tick, 1000);
            </script>
            """, height=0)
            st.markdown('<p id="arc" style="font-size:0.78em;color:#888;margin-top:-8px;"></p>',
                        unsafe_allow_html=True)
        else:
            st.caption("Auto-refresh is off.")

        st.markdown("---")
        st.markdown("**⚠️ Risk Thresholds**")
        with st.sidebar.expander("🌊 Level (cm)"):
            RISK_THRESHOLDS["level_cm"]["alert"]    = (
                st.number_input("Alert low",  value=55.0, step=1.0, key="l_al"),
                st.number_input("Alert high", value=65.0, step=1.0, key="l_ah"),
            )
            RISK_THRESHOLDS["level_cm"]["critical"]  = (
                RISK_THRESHOLDS["level_cm"]["alert"][1], 9999,
            )
        with st.sidebar.expander("💧 Turbidity (NTU)"):
            RISK_THRESHOLDS["turb_ntu"]["alert"]    = (
                st.number_input("Alert low",  value=3.0, step=0.1, key="t_al"),
                st.number_input("Alert high", value=5.0, step=0.1, key="t_ah"),
            )
            RISK_THRESHOLDS["turb_ntu"]["critical"] = (
                RISK_THRESHOLDS["turb_ntu"]["alert"][1], 9999,
            )
        with st.sidebar.expander("🔄 Flow (L/min)"):
            RISK_THRESHOLDS["flow_lpm"]["alert"]    = (
                st.number_input("Alert low",  value=8.0,  step=0.5, key="f_al"),
                st.number_input("Alert high", value=12.0, step=0.5, key="f_ah"),
            )
            RISK_THRESHOLDS["flow_lpm"]["critical"] = (
                RISK_THRESHOLDS["flow_lpm"]["alert"][1], 9999,
            )
        st.sidebar.markdown("---")
        st.sidebar.markdown(
            "<small style='color:#aaa'>📡 Arduino → FastAPI → Dashboard<br>"
            "⚡ XGBoost Recursive Forecast<br>"
            "🎓 Laurentian University</small>",
            unsafe_allow_html=True,
        )

    # ── Professional header banner ────────────────────────────────────────────
    now_display = pd.Timestamp.now().strftime("%d %b %Y  %H:%M:%S")
    st.markdown(f"""
    <div class="tsf-header">
        <div>
            <h1>🛡️ Tailings Storage Facility — AI Monitoring Dashboard</h1>
            <div class="subtitle">
                Real-time sensor monitoring · XGBoost 60-minute forecasting ·
                Composite risk scoring · Laurentian University
            </div>
        </div>
        <div style="text-align:right">
            <div class="tsf-badge">🟢 LIVE</div>
            <div style="color:#94b8c4;font-size:0.75rem;margin-top:6px">{now_display}</div>
        </div>
    </div>
    """, unsafe_allow_html=True)

    # ── Live feed (fragment — no full page reload) ───────────────────────────
    # _make_live_fragment() binds sidebar settings and returns a fragment
    # decorated with run_every=refresh_interval so Streamlit re-runs ONLY
    # this block on the timer, leaving the static header/sidebar untouched.
    _frag = _make_live_fragment(history_minutes, refresh_interval if auto_refresh else 0)
    _frag()


if __name__ == "__main__":
    main()